parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "platform": {
      "type": "string",
      "enum": ["LinkedIn", "JobStreet", "Indeed", "OLJ PH", "Generic"],
      "description": "The website where the job was posted. Use 'Generic' if the website is not LinkedIn, JobStreet, Indeed, or OLJ PH."
    },
    "company_name": {
      "type": "string",
      "description": "The extracted name of the hiring company. Use 'Undisclosed' if missing."
    },
    "job_title": {
      "type": "string",
      "description": "The official job or role title."
    },
    "cleaned_job_description": {
      "type": "string",
      "description": "A single continuous clean string summarizing core responsibilities and tech stack rules. Strictly no newlines or bullet points."
    },
    "application_instructions": {
      "type": "string",
      "description": "Extracted application directions, questions to answer, required application keywords, or Loom video requests. Output 'None' if the application process is standard."
    },
    "has_special_requirements": {
      "type": "boolean",
      "description": "Set to true if application_instructions contains specific questions, required words, or video requests. Set to false if it is standard."
    },
    "search_keywords": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "An array containing exactly 5 relevant search keywords or phrases."
    }
  },
  "required": ["platform", "company_name", "job_title", "cleaned_job_description", "application_instructions", "has_special_requirements", "search_keywords"]
}

{
  "type": "object",
  "properties": {
    "match_confidence_score": {
      "type": "number",
      "description": "A strict scoring metric from 0 to 100 assessing how well the Candidate Master Document natively matches the Core Job Requirements."
    },
    "automation_decision": {
      "type": "string",
      "enum": ["TAILOR_RESUME", "SKIP_AND_REPORT"],
      "description": "Output exactly 'TAILOR_RESUME' if the match_confidence_score is 80 or above. Output exactly 'SKIP_AND_REPORT' if the score is below 80."
    },
    "missing_keywords_and_tools": {
      "type": "array",
      "items": { "type": "string" },
      "description": "A list of critical technical skills, software stack tools, or industry terms required by the job posting that are completely missing from the candidate's master document."
    },
    "knowledge_base_improvement_suggestions": {
      "type": "string",
      "description": "Strategic, detailed instructions advising the user on what projects to execute or details to append to their master file to fulfill this gap."
    }
  },
  "required": ["match_confidence_score", "automation_decision", "missing_keywords_and_tools", "knowledge_base_improvement_suggestions"]
}

