parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "professional_summary": {
      "type": "string",
      "description": "A 3-4 sentence impactful professional summary tailored to the target job, highlighting AI automation, low-code engine capabilities, and full-stack development enthusiasm using a direct, execution-focused technical voice."
    },
    "tailored_skills_matrix": {
      "type": "string",
      "description": "A continuous, neatly formatted comma-separated list of specific technical tools, languages, and frameworks pulled from the Master Doc that directly match the target job description requirements. No bullet points."
    },
    "resume_experience_block": {
      "type": "string",
      "description": "Tailored technical bullet points for your roles at The ValueMed Generics Co. Reframe tasks to highlight database optimization, SQL fixes, and tool efficiency using strong engineering verbs. No corporate fluff."
    },
    "resume_projects_block": {
      "type": "string",
      "description": "Select and summarize 2-3 of the most relevant portfolio projects from the Master Doc (e.g., Automated Job Application System, Lead Enrichment System) that highlight your exact use of n8n, Webhooks, and Gemini APIs."
    }
  },
  "required": ["professional_summary", "tailored_skills_matrix", "resume_experience_block", "resume_projects_block"]
}

